def main():
    if not TARGET.exists():
        print(f"ВНИМАНИЕ: {TARGET} не найден -- патч фазы 1 применён?")
        sys.exit(1)
    content = base64.b64decode("".join(_B64_CHUNKS)).decode("utf-8")
    TARGET.write_text(content, encoding="utf-8")
    print("=" * 62)
    print("ENGINE_ONE_DOOR_V1 -- фаза 2 применена")
    print("=" * 62)
    print("  [обновлён] Биржа/ui_torg.py")
    print()
    print("Кабинет (кнопка РЫНОК) теперь зовёт ту же дверь Совета,")
    print("что и тестер -- council.wake_council(). Обе руки Биржи")
    print("(тестовая и живая) ведут себя из одного источника правды.")
    print()
    print("ВАЖНО: ворота изменились -- кабинет больше не смотрит на")
    print("t1_status для решения будить ли остальных. Он смотрит на")
    print("флаг idle из wake_council (закон спуска, как у тестера).")
    print()
    print("Остаток архитектуры (следующий заход, по твоему слову):")
    print("  -- решить судьбу hooks.run_live_council() (боевой путь)")
    print("  -- охват памяти конторы (общий котёл + метка цеха)")


if __name__ == "__main__":
    if not (REPO_ROOT / "GRONDHEIM_CITY").exists() or not (REPO_ROOT / "Биржа").exists():
        print("ВНИМАНИЕ: рядом со скриптом нет GRONDHEIM_CITY/ и Биржа/.")
        print("    Запусти патч из корня репозитория Grondheim-Ecosystem.")
        sys.exit(1)
    main()
